"use client";

import { useState } from "react";
import { SITE } from "@/lib/nav-data";

export default function ContactForm() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [message, setMessage] = useState("");

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    const body = `Name: ${name}%0APhone: ${phone}%0A%0A${message}`;
    window.location.href = `mailto:${SITE.email}?subject=Website Enquiry from ${encodeURIComponent(
      name
    )}&body=${body}`;
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div>
        <label className="text-sm text-navy block mb-1">Name</label>
        <input
          required
          value={name}
          onChange={(e) => setName(e.target.value)}
          className="w-full border border-navy/20 px-4 py-2 bg-white text-navy focus:outline-none focus:border-olive"
        />
      </div>
      <div>
        <label className="text-sm text-navy block mb-1">Email</label>
        <input
          required
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          className="w-full border border-navy/20 px-4 py-2 bg-white text-navy focus:outline-none focus:border-olive"
        />
      </div>
      <div>
        <label className="text-sm text-navy block mb-1">Phone</label>
        <input
          value={phone}
          onChange={(e) => setPhone(e.target.value)}
          className="w-full border border-navy/20 px-4 py-2 bg-white text-navy focus:outline-none focus:border-olive"
        />
      </div>
      <div>
        <label className="text-sm text-navy block mb-1">How can we help?</label>
        <textarea
          required
          rows={4}
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          className="w-full border border-navy/20 px-4 py-2 bg-white text-navy focus:outline-none focus:border-olive"
        />
      </div>
      <button type="submit" className="bg-olive text-white px-6 py-3 text-sm tracking-wide">
        Send Message
      </button>
      <p className="text-xs text-slate">This opens your email app with the details pre-filled.</p>
    </form>
  );
}
